$Tokens=$null;$Errors=$null;$Ast=[Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$Errors);if($Errors.Count-ne0){throw 'negative: PhaseMerge parser errors detected'}
